functions.stateless_host_exec_witness._build_pre_s:
def _build_pre_state_storage_mpts(
    pre_state_storages_data: Dict[Address, Trie[Bytes32, U256]],
) -> Dict[Address, IncrementalMPT[Bytes32, U256]]:
    """Build incremental storage MPTs from pre-state flat storage data."""
    incr_storage_mpts: Dict[Address, IncrementalMPT[Bytes32, U256]] = {}
    for address, data in pre_state_storages_data.items():
        incr_storage_mpts[address] = build_mpt(
            data._data, secured=True, default=U256(0)
        )
    return incr_storage_mpts

def _build_pre_state_account_mpt(
    pre_state_accounts_data: Trie[Address, Optional[Account]],
    incr_storage_mpts: Dict[Address, IncrementalMPT[Bytes32, U256]],
) -> IncrementalMPT[Address, Optional[Account]]:
    """Build the incremental account MPT from pre-state flat account data."""

    def get_pre_storage_root(address: Address) -> Root:
        if address in incr_storage_mpts:
            return mpt_root(incr_storage_mpts[address])
        return EMPTY_TRIE_ROOT

    return build_mpt(
        pre_state_accounts_data._data,
        secured=True,
        default=None,
        get_storage_root=get_pre_storage_root,
    )

functions.stateless_host_exec_witness._collect_sto:
def _collect_storage_accesses(
    block_state: BlockState,
) -> Dict[Address, Set[Bytes32]]:
    """
    Collect all storage keys that must be traversed on pre-state tries.

    Includes both reads and writes so all needed pre-state nodes are captured
    before in-place mutation.
    """
    all_storage_accesses: Dict[Address, Set[Bytes32]] = {}
    for address, key in block_state.storage_reads:
        all_storage_accesses.setdefault(address, set()).add(key)
    for address, slots in block_state.storage_writes.items():
        all_storage_accesses.setdefault(address, set()).update(slots)
    return all_storage_accesses

functions.stateless_host_exec_witness._capture_pre:
def _capture_pre_state_storage_nodes(
    incr_storage_mpts: Dict[Address, IncrementalMPT[Bytes32, U256]],
    all_storage_accesses: Dict[Address, Set[Bytes32]],
) -> None:
    """Traverse pre-state storage tries to record witness nodes."""
    for address, keys in all_storage_accesses.items():
        if address not in incr_storage_mpts:
            continue
        for key in keys:
            mpt_get(incr_storage_mpts[address], key)

functions.stateless_host_exec_witness._apply_stora:
def _apply_storage_writes(
    incr_storage_mpts: Dict[Address, IncrementalMPT[Bytes32, U256]],
    storage_writes: Dict[Address, Dict[Bytes32, U256]],
) -> None:
    """Apply block storage writes to incremental storage MPTs."""
    for address, dirty_keys in storage_writes.items():
        if address not in incr_storage_mpts:
            # New storage created during block.
            incr_storage_mpts[address] = build_mpt(
                {}, secured=True, default=U256(0)
            )

        # Two passes: insert/update first, deletions second.
        for key, value in dirty_keys.items():
            if value != 0:
                mpt_set(incr_storage_mpts[address], key, value)
        for key, value in dirty_keys.items():
            if value == 0:
                mpt_set(incr_storage_mpts[address], key, value)

functions.stateless_host_exec_witness._get_all_dir:
def _get_all_dirty_accounts(block_state: BlockState) -> Set[Address]:
    """Return addresses whose account leaf may change in the state trie."""
    return set(block_state.account_writes.keys()) | set(
        block_state.storage_writes.keys()
    )

functions.stateless_host_exec_witness._capture_pre:
def _capture_pre_state_account_nodes(
    incr_account_mpt: IncrementalMPT[Address, Optional[Account]],
    account_reads: Set[Address],
    all_dirty_accounts: Set[Address],
) -> None:
    """Traverse pre-state account trie to record witness nodes."""
    for address in account_reads | all_dirty_accounts:
        mpt_get(incr_account_mpt, address)

functions.stateless_host_exec_witness._apply_accou:
def _apply_account_writes(
    incr_account_mpt: IncrementalMPT[Address, Optional[Account]],
    incr_storage_mpts: Dict[Address, IncrementalMPT[Bytes32, U256]],
    block_state: BlockState,
    all_dirty_accounts: Set[Address],
) -> None:
    """Apply final account values and post-storage roots to account trie."""
    for address in all_dirty_accounts:
        if address in block_state.account_writes:
            account = block_state.account_writes[address]
        else:
            account = block_state.pre_state.get_account_optional(address)

        if address in incr_storage_mpts:
            addr_storage_root = mpt_root(incr_storage_mpts[address])
        else:
            addr_storage_root = EMPTY_TRIE_ROOT

        def get_storage_root_fn(
            _: Address, sr: Root = addr_storage_root
        ) -> Root:
            return sr

        mpt_set(
            incr_account_mpt,
            address,
            account,
            get_storage_root=get_storage_root_fn,
        )

functions.stateless_host_exec_witness._collect_acc:
def _collect_accessed_nodes(
    incr_account_mpt: IncrementalMPT[Address, Optional[Account]],
    incr_storage_mpts: Dict[Address, IncrementalMPT[Bytes32, U256]],
) -> Dict[Bytes, Bytes]:
    """Merge accessed trie nodes from account and storage witnesses."""
    accessed_nodes = dict(incr_account_mpt.witness.accessed_nodes)
    for mpt in incr_storage_mpts.values():
        accessed_nodes.update(mpt.witness.accessed_nodes)
    return accessed_nodes

functions.transactions.encode_transaction:
def encode_transaction(tx: Transaction) -> LegacyTransaction | Bytes:
    """
    Encode a transaction into its RLP or typed transaction format.
    Needed because non-legacy transactions aren't RLP.

    Legacy transactions are returned as-is, while other transaction types
    are prefixed with their type identifier and RLP encoded.
    """
    if isinstance(tx, LegacyTransaction):
        return tx
    elif isinstance(tx, AccessListTransaction):
        return b"\x01" + rlp.encode(tx)
    elif isinstance(tx, FeeMarketTransaction):
        return b"\x02" + rlp.encode(tx)
    elif isinstance(tx, BlobTransaction):
        return b"\x03" + rlp.encode(tx)
    elif isinstance(tx, SetCodeTransaction):
        return b"\x04" + rlp.encode(tx)
    else:
        raise Exception(f"Unable to encode transaction of type {type(tx)}")

functions.transactions.decode_transaction:
def decode_transaction(tx: LegacyTransaction | Bytes) -> Transaction:
    """
    Decode a transaction from its RLP or typed transaction format.
    Needed because non-legacy transactions aren't RLP.

    Accept a ``LegacyTransaction`` object (returned as-is) or raw
    bytes.

    EIP-2718 states that the first byte distinguishes the format:
    [0x00, 0x7f] is a typed transaction, [0xc0, 0xfe] is a legacy
    transaction (RLP list prefix).
    """
    if isinstance(tx, Bytes):
        if tx[0] == 1:
            return rlp.decode_to(AccessListTransaction, tx[1:])
        elif tx[0] == 2:
            return rlp.decode_to(FeeMarketTransaction, tx[1:])
        elif tx[0] == 3:
            return rlp.decode_to(BlobTransaction, tx[1:])
        elif tx[0] == 4:
            return rlp.decode_to(SetCodeTransaction, tx[1:])
        elif tx[0] >= 0xC0:
            assert tx[0] <= 0xFE
            return rlp.decode_to(LegacyTransaction, tx)
        else:
            raise TransactionTypeError(tx[0])
    else:
        return tx

functions.transactions.validate_transaction:
def validate_transaction(tx: Transaction, sender: Address) -> IntrinsicGasCost:
    """
    Verifies a transaction.

    The gas in a transaction gets used to pay for the intrinsic cost of
    operations, therefore if there is insufficient gas then it would not
    be possible to execute a transaction and it will be declared invalid.

    Additionally, the nonce of a transaction must not equal or exceed the
    limit defined in [EIP-2681].
    In practice, defining the limit as ``2**64-1`` has no impact because
    sending ``2**64-1`` transactions is improbable. It's not strictly
    impossible though, ``2**64-1`` transactions is the entire capacity of the
    Ethereum blockchain at 2022 gas limits for a little over 22 years.

    Also, the code size of a contract creation transaction must be within
    limits of the protocol.

    This function takes a transaction and gas_limit as parameters and
    returns the intrinsic gas costs for the transaction after validation.
    It throws an `InsufficientTransactionGasError` exception if the
    transaction does not provide enough gas to cover the intrinsic cost,
    and a `NonceOverflowError` exception if the nonce overflows.
    It also raises an `InitCodeTooLargeError` if the code
    size of a contract creation transaction exceeds the maximum allowed
    size, and a `PriorityFeeGreaterThanMaxFeeError` if the maximum
    priority fee per gas of a fee market transaction exceeds its maximum
    fee per gas.

    [EIP-2681]: https://eips.ethereum.org/EIPS/eip-2681
    [EIP-7623]: https://eips.ethereum.org/EIPS/eip-7623
    """
    from .vm.interpreter import MAX_INIT_CODE_SIZE

    if U256(tx.nonce) >= U256(U64.MAX_VALUE):
        raise NonceOverflowError("Nonce too high")

    if tx.to == Bytes0(b"") and len(tx.data) > MAX_INIT_CODE_SIZE:
        raise InitCodeTooLargeError("Code size too large")

    if isinstance(tx, FeeMarketCapableTransaction):
        if tx.max_fee_per_gas < tx.max_priority_fee_per_gas:
            raise PriorityFeeGreaterThanMaxFeeError(
                "priority fee greater than max fee"
            )

    if isinstance(tx, BlobTransaction):
        blob_count = len(tx.blob_versioned_hashes)
        if blob_count == 0:
            raise NoBlobDataError("no blob data in transaction")
        if blob_count > BLOB_COUNT_LIMIT:
            raise BlobCountExceededError(
                f"Tx has {blob_count} blobs. Max allowed: {BLOB_COUNT_LIMIT}"
            )
        for blob_versioned_hash in tx.blob_versioned_hashes:
            if blob_versioned_hash[0:1] != VERSIONED_HASH_VERSION_KZG:
                raise InvalidBlobVersionedHashError(
                    "invalid blob versioned hash"
                )

    if isinstance(tx, (BlobTransaction, SetCodeTransaction)):
        if not isinstance(tx.to, Address):
            raise TransactionTypeContractCreationError(tx)

    if isinstance(tx, SetCodeTransaction):
        if not any(tx.authorizations):
            raise EmptyAuthorizationListError("empty authorization list")

    intrinsic = calculate_intrinsic_cost(tx, sender)
    intrinsic_gas = Uint(intrinsic.execution)
    if intrinsic_gas > tx.gas:
        raise InsufficientTransactionGasError("Insufficient intrinsic gas")
    if intrinsic.calldata_floor > tx.gas:
        raise InsufficientTransactionGasError("Insufficient calldata floor")
    if intrinsic.execution > TX_MAX_GAS_LIMIT:
        raise InsufficientTransactionGasError(
            "Intrinsic execution gas exceeds TX_MAX_GAS_LIMIT"
        )
    if intrinsic.calldata_floor > TX_MAX_GAS_LIMIT:
        raise InsufficientTransactionGasError(
            "Intrinsic calldata floor exceeds TX_MAX_GAS_LIMIT"
        )

    return intrinsic

functions.transactions.check_nonce:
def check_nonce(tx: Transaction, sender_nonce: Uint) -> None:
    """
    Check that the transaction's nonce equals the sender's next nonce.
    """
    if sender_nonce > Uint(tx.nonce):
        raise NonceMismatchError("nonce too low")
    elif sender_nonce < Uint(tx.nonce):
        raise NonceMismatchError("nonce too high")

functions.transactions.chain_id:
def chain_id(tx: Transaction) -> None | U64:
    """
    Extract the chain identifier from a transaction. See [EIP-155].

    [EIP-155]: https://eips.ethereum.org/EIPS/eip-155
    """
    if isinstance(tx, LegacyTransaction):
        if tx.v == 27 or tx.v == 28:
            return None

        if tx.v < U256(35):
            raise InvalidSignatureError("bad v")

        return U64((tx.v - U256(35)) >> U256(1))
    else:
        return tx.chain_id

functions.transactions.recover_transaction_public_:
def recover_transaction_public_key(chain_id: U64, tx: Transaction) -> Bytes:
    """
    Recover the canonical uncompressed SEC1 public key for a transaction.
    """
    r, s, recovery_id, signing_hash = _signature_recovery_parameters(
        chain_id, tx
    )
    return Bytes(
        SECP256K1_UNCOMPRESSED_PUBLIC_KEY_PREFIX
        + secp256k1_recover(r, s, recovery_id, signing_hash)
    )

functions.transactions._sender_address_from_public:
def _sender_address_from_public_key(public_key: Bytes) -> Address:
    """
    Derive the sender address from an uncompressed SEC1 public key.
    """
    return Address(keccak256(bytes(public_key)[1:])[12:32])

functions.transactions._signature_recovery_paramet:
def _signature_recovery_parameters(
    chain_id: U64, tx: Transaction
) -> Tuple[U256, U256, U256, Hash32]:
    """
    Validate the transaction signature fields and return recovery inputs.
    """
    r, s = tx.r, tx.s
    if U256(0) >= r or r >= SECP256K1N:
        raise InvalidSignatureError("bad r")
    if U256(0) >= s or s > SECP256K1N // U256(2):
        raise InvalidSignatureError("bad s")

    if isinstance(tx, LegacyTransaction):
        v = tx.v
        if v == 27 or v == 28:
            return (
                r,
                s,
                v - U256(27),
                signing_hash_pre155(tx),
            )
        else:
            chain_id_x2 = U256(chain_id) * U256(2)
            if v != U256(35) + chain_id_x2 and v != U256(36) + chain_id_x2:
                raise InvalidSignatureError("bad v")
            return (
                r,
                s,
                v - U256(35) - chain_id_x2,
                signing_hash_155(tx, chain_id),
            )
    elif isinstance(tx, AccessListTransaction):
        if tx.y_parity not in (U256(0), U256(1)):
            raise InvalidSignatureError("bad y_parity")
        return (
            r,
            s,
            tx.y_parity,
            signing_hash_2930(tx),
        )
    elif isinstance(tx, FeeMarketTransaction):
        if tx.y_parity not in (U256(0), U256(1)):
            raise InvalidSignatureError("bad y_parity")
        return (
            r,
            s,
            tx.y_parity,
            signing_hash_1559(tx),
        )
    elif isinstance(tx, BlobTransaction):
        if tx.y_parity not in (U256(0), U256(1)):
            raise InvalidSignatureError("bad y_parity")
        return (
            r,
            s,
            tx.y_parity,
            signing_hash_4844(tx),
        )
    elif isinstance(tx, SetCodeTransaction):
        if tx.y_parity not in (U256(0), U256(1)):
            raise InvalidSignatureError("bad y_parity")
        return (
            r,
            s,
            tx.y_parity,
            signing_hash_7702(tx),
        )
    else:
        raise InvalidSignatureError("unsupported transaction type")

functions.transactions.get_transaction_hash:
def get_transaction_hash(tx: Bytes | LegacyTransaction) -> Hash32:
    """
    Compute the hash of a transaction.

    This function takes a transaction as a parameter and returns the
    keccak256 hash of the transaction. It can handle both legacy transactions
    and typed transactions (`AccessListTransaction`, `FeeMarketTransaction`,
    etc.).
    """
    assert isinstance(tx, (LegacyTransaction, Bytes))
    if isinstance(tx, LegacyTransaction):
        return keccak256(rlp.encode(tx))
    else:
        return keccak256(tx)

