functions.witness_state._trie_lookup:
def _trie_lookup(
    root_node: MutableNode,
    key_hash: Hash32,
) -> Optional[Bytes]:
    """
    Walk a decoded MPT from root following nibblized key_hash.

    Return leaf value or ``None`` if not found.

    """
    nibbles = bytearray()
    for byte in key_hash:
        nibbles.append(byte >> 4)
        nibbles.append(byte & 0x0F)

    node = root_node
    pos = 0

    while node is not None:
        if isinstance(node, HashedNode):
            raise AssertionError(
                "Encountered unresolved HashedNode during witness lookup"
            )

        if isinstance(node, MutableLeafNode):
            if bytes(nibbles[pos:]) == node.rest_of_key:
                return node.value
            return None

        if isinstance(node, MutableExtensionNode):
            segment = node.key_segment
            if bytes(nibbles[pos : pos + len(segment)]) != segment:
                return None
            pos += len(segment)
            node = node.child
            continue

        assert isinstance(node, MutableBranchNode), (
            f"Unexpected node type {type(node)}"
        )

        if pos == len(nibbles):
            return node.value or None
        idx = nibbles[pos]
        pos += 1
        node = node.children[idx]

    return None

dataclasses.fork_types.StateGasPerByte:
class StateGasPerByte:
    """
    State gas charged per byte of state growth, per [EIP-8037].

    A rate, not an amount: deliberately not a `Uint`, since adding a rate to
    a gas amount is meaningless. Multiplying it by a byte count, in either
    operand order, yields a `StateGas`.

    [EIP-8037]: https://eips.ethereum.org/EIPS/eip-8037
    """

    rate: Uint

    def __mul__(self, num_bytes: Uint) -> StateGas:
        """Return the state gas for `num_bytes` charged at this rate."""
        return StateGas(self.rate * num_bytes)

    def __rmul__(self, num_bytes: Uint) -> StateGas:
        """Return the state gas for `num_bytes` charged at this rate."""
        return StateGas(self.rate * num_bytes)

